"""The command line, built from manifest.json. Generated by anything-anything from anything.toml."""

from __future__ import annotations

import argparse
import importlib
import json
import sys
from pathlib import Path
from types import SimpleNamespace
from typing import Any

from . import __version__
from .output import Output

MANIFEST: dict[str, Any] = json.loads((Path(__file__).parent / "manifest.json").read_text(encoding="utf-8"))
TYPES: dict[str, Any] = {"string": str, "path": str, "int": int, "float": float}


def _csv(value: str) -> list[str]:
    return [v.strip() for v in value.split(",") if v.strip()]


def _add(parser: argparse.ArgumentParser, arg: dict[str, Any]) -> None:
    kind, default, help_ = arg["kind"], arg["default"], arg["help"] or None
    if arg["positional"]:
        if kind == "list":
            nargs = "+" if arg["required"] else "*"
            parser.add_argument(arg["key"], nargs=nargs, default=default, help=help_, metavar=arg["name"])
        else:
            nargs = None if arg["required"] else "?"
            parser.add_argument(
                arg["key"], type=TYPES[kind], nargs=nargs, default=default, help=help_, metavar=arg["name"]
            )
        return
    flag = "--" + arg["name"]
    if kind == "bool":
        parser.add_argument(flag, dest=arg["key"], action="store_true", help=help_)
    elif kind == "list":
        parser.add_argument(flag, dest=arg["key"], type=_csv, default=default, help=help_)
    else:
        required = arg["required"]
        parser.add_argument(flag, dest=arg["key"], type=TYPES[kind], default=default, required=required, help=help_)


def parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(prog=MANIFEST["name"], description=MANIFEST["pitch"])
    p.add_argument("--version", action="version", version=f"%(prog)s {__version__}")
    common = argparse.ArgumentParser(add_help=False)
    common.add_argument("--json", action="store_true", help="print the result as JSON")
    sub = p.add_subparsers(dest="command", metavar="<command>")
    for command in MANIFEST["commands"]:
        sp = sub.add_parser(command["name"], help=command["about"], description=command["about"], parents=[common])
        for arg in command["args"]:
            _add(sp, arg)
    sub.add_parser("mcp", help="run as an MCP server on stdio (Claude Code, Codex, Cursor, ...)")
    return p


def command_def(name: str) -> dict[str, Any]:
    return next(c for c in MANIFEST["commands"] if c["name"] == name)


def args_from(command: dict[str, Any], values: dict[str, Any]) -> SimpleNamespace:
    """A command's arguments from a dict (an MCP call): defaults filled in, unknown keys refused."""
    known = {a["key"]: a for a in command["args"]}
    extra = sorted(set(values) - set(known))
    if extra:
        raise ValueError(f"unknown argument(s): {', '.join(extra)}")
    out: dict[str, Any] = {}
    for key, arg in known.items():
        if key in values:
            out[key] = values[key]
        elif arg["required"]:
            raise ValueError(f"{key} is required")
        else:
            out[key] = arg["default"]
    return SimpleNamespace(**out)


def run_command(name: str, args: SimpleNamespace) -> Output:
    module = importlib.import_module(f"{__package__}.commands.{command_def(name)['module']}")
    return module.run(args)


def main(argv: list[str] | None = None) -> int:
    for stream in (sys.stdin, sys.stdout, sys.stderr):
        if hasattr(stream, "reconfigure"):
            stream.reconfigure(encoding="utf-8")
    p = parser()
    ns = p.parse_args(argv)
    if ns.command is None:
        p.print_help()
        return 2
    if ns.command == "mcp":
        from .mcp import serve

        return serve()
    command = command_def(ns.command)
    args = SimpleNamespace(**{a["key"]: getattr(ns, a["key"]) for a in command["args"]})
    try:
        out = run_command(ns.command, args)
    except Exception as e:  # a failed command: the reason on stderr, exit 1
        print(f"✗ {e}", file=sys.stderr)
        return 1
    out.print(ns.json)
    return out.exit
